script:
(function(root_element) {
'use strict';

var hxMap, hxMarkers = [], hxMapData = null, hxCurrentView = 'meter';

function hxParseCoord(val) {
    if (val === null || val === undefined) return NaN;
    return parseFloat(String(val).replace('°', '').trim());
}

function hxNum(val, decimals) {
    var n = Number(val || 0);
    return n.toLocaleString(undefined, { maximumFractionDigits: decimals === undefined ? 0 : decimals });
}

function hxDate(val) {
    if (!val) return '—';
    return frappe.datetime.str_to_user(val, true);
}

function hxInjectLeafletCSS() {
    var root = root_element.getRootNode ? root_element.getRootNode() : document;
    if (root.querySelector && root.querySelector('link[data-hx-leaflet]')) return;
    var links = document.querySelectorAll('link[rel="stylesheet"]');
    links.forEach(function(l) {
        if (l.href.indexOf('leaflet') !== -1) {
            var clone = l.cloneNode(true);
            clone.setAttribute('data-hx-leaflet', '1');
            if (root.appendChild) root.appendChild(clone);
        }
    });
}

function hxLoadLeaflet(cb) {
    function ready() {
        hxInjectLeafletCSS();
        cb();
    }
    if (window.L && typeof window.L.map === 'function') { ready(); return; }
    frappe.require("leaflet.bundle.js", function() {
        frappe.require("leaflet.bundle.css", function() {
            var tries = 0;
            var check = setInterval(function() {
                tries++;
                if (window.L && typeof window.L.map === 'function') {
                    clearInterval(check);
                    ready();
                } else if (tries > 40) {
                    clearInterval(check);
                    console.error('Leaflet failed to load properly');
                }
            }, 50);
        });
    });
}

function hxLoadSummary() {
    frappe.call({
        method: "upande_hydrax.upande_hydrax.api.get_dashboard_summary",
        callback: function(r) {
            var d = r.message;
            root_element.querySelector('#hx-dcu-online').textContent = d.online_dcu;
            root_element.querySelector('#hx-dcu-total').textContent = 'of ' + d.total_dcu + ' total';
            root_element.querySelector('#hx-dcu-offline').textContent = d.offline_dcu;
            root_element.querySelector('#hx-kpi-offline-dcu').classList.toggle('hx-kpi-warn', d.offline_dcu > 0);
            root_element.querySelector('#hx-meter-total').textContent = d.total_meters;
            root_element.querySelector('#hx-meter-active').textContent = d.active_meters + ' reporting today';
            root_element.querySelector('#hx-meter-faulty').textContent = d.faulty_meters;
            root_element.querySelector('#hx-kpi-faulty-meter').classList.toggle('hx-kpi-warn', d.faulty_meters > 0);
            root_element.querySelector('#hx-consumption').textContent = hxNum(d.total_consumption_today, 1);
            root_element.querySelector('#hx-revenue-today').textContent = hxNum(d.revenue_today, 2);
            root_element.querySelector('#hx-revenue-month').textContent = hxNum(d.revenue_month, 2) + ' this month';
        }
    });
}

function hxLoadSites() {
    frappe.call({
        method: "upande_hydrax.upande_hydrax.api.get_site_list",
        callback: function(r) {
            var select = root_element.querySelector('#hx-site-filter');
            (r.message || []).forEach(function(s) {
                var opt = document.createElement('option');
                opt.value = s.site;
                opt.textContent = s.site;
                select.appendChild(opt);
            });
        }
    });
}

function hxLoadSiteTable() {
    frappe.call({
        method: "upande_hydrax.upande_hydrax.api.get_site_breakdown",
        callback: function(r) {
            var rows = r.message || [];
            var tbody = root_element.querySelector('#hx-site-table tbody');
            if (!rows.length) {
                tbody.innerHTML = '<tr><td colspan="4" class="hx-table-empty">No sites yet</td></tr>';
                return;
            }
            tbody.innerHTML = rows.map(function(row) {
                return '<tr><td>' + row.site + '</td><td>' + row.meter_count + '</td><td>' + hxNum(row.consumption_today, 1) + ' L</td><td>' + hxNum(row.revenue_today, 2) + '</td></tr>';
            }).join('');
        }
    });
}

function hxLoadRecentTokens(tokenType) {
    frappe.call({
        method: "upande_hydrax.upande_hydrax.api.get_recent_token_records",
        args: { limit: 8, token_type: tokenType || null },
        callback: function(r) {
            var rows = r.message || [];
            var tbody = root_element.querySelector('#hx-token-table tbody');
            if (!rows.length) {
                tbody.innerHTML = '<tr><td colspan="6" class="hx-table-empty">No token records yet</td></tr>';
                return;
            }
            tbody.innerHTML = rows.map(function(row) {
                return '<tr><td>' + (row.receipt_id || '—') + '</td><td>' + (row.customer_name || '—') + '</td><td>' + (row.meter || '—') + '</td><td>' + hxNum(row.amount_paid, 2) + '</td><td>' + (row.type || '—') + '</td><td>' + hxDate(row.created_date) + '</td></tr>';
            }).join('');
        }
    });
}

function hxRenderTrendChart(containerId, method, seriesName, color) {
    frappe.call({
        method: method,
        args: { days: 14 },
        callback: function(r) {
            var data = r.message;
            var container = root_element.querySelector('#' + containerId);
            if (!data.labels.length) {
                container.innerHTML = '<p class="hx-chart-empty">No data for this period yet.</p>';
                return;
            }
            new frappe.Chart(container, {
                data: {
                    labels: data.labels,
                    datasets: [{ name: seriesName, values: data.values }]
                },
                type: 'line',
                height: 220,
                lineOptions: { regionFill: 1 },
                colors: [color]
            });
        }
    });
}

function hxRenderMarkers() {
    if (!hxMap || !hxMapData) return;
    hxMarkers.forEach(function(m) { hxMap.removeLayer(m); });
    hxMarkers = [];

    var points = hxCurrentView === 'dcu' ? hxMapData.dcus : hxMapData.meters;
    var bounds = [];

    points.forEach(function(p) {
        var lat = hxParseCoord(p.latitude);
        var lng = hxParseCoord(p.longitude);
        if (isNaN(lat) || isNaN(lng)) return;

        var color = hxCurrentView === 'dcu'
            ? (p.status === 'Online' ? '#10b981' : '#ef4444')
            : (p.status === 'Faulty' ? '#ef4444' : '#3b82f6');
        var marker = L.circleMarker([lat, lng], {
            radius: hxCurrentView === 'dcu' ? 8 : 6,
            fillColor: color, color: '#fff', weight: 2, fillOpacity: 1
        }).addTo(hxMap);
        var label = hxCurrentView === 'dcu'
            ? '<b>DCU: ' + (p.dcu_name || p.dcu_id) + '</b><br>Status: ' + p.status
            : '<b>Meter: ' + p.meter_id + '</b><br>House: ' + (p.house_number || '—') + '<br>Site: ' + (p.site || '—') + '<br>Status: ' + (p.status || '—');
        marker.bindPopup(label);
        hxMarkers.push(marker);
        bounds.push([lat, lng]);
    });

    if (bounds.length) hxMap.fitBounds(bounds, { padding: [30, 30] });
}

function hxLoadMapData(site) {
    frappe.call({
        method: "upande_hydrax.upande_hydrax.api.get_map_points",
        args: { site: site || null },
        callback: function(r) {
            hxMapData = r.message;
            hxRenderMarkers();
            setTimeout(function() { hxMap.invalidateSize(); }, 100);
        }
    });
}

function hxInitMap() {
    hxLoadLeaflet(function() {
        hxMap = L.map(root_element.querySelector('#hx-map')).setView([-1.286389, 36.817223], 7);

        var streetLayer = L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
            attribution: '&copy; OpenStreetMap contributors'
        });
        var satelliteLayer = L.tileLayer('https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}', {
            attribution: '&copy; Esri'
        });

        streetLayer.addTo(hxMap);

        L.control.layers(
            { "Street": streetLayer, "Satellite": satelliteLayer },
            null,
            { position: 'topright' }
        ).addTo(hxMap);

        setTimeout(function() { hxMap.invalidateSize(); }, 200);
        hxLoadMapData();
    });
}

root_element.querySelector('#hx-view-dcu').addEventListener('click', function() {
    hxCurrentView = 'dcu';
    root_element.querySelector('#hx-view-dcu').classList.add('active');
    root_element.querySelector('#hx-view-meter').classList.remove('active');
    hxRenderMarkers();
});
root_element.querySelector('#hx-view-meter').addEventListener('click', function() {
    hxCurrentView = 'meter';
    root_element.querySelector('#hx-view-meter').classList.add('active');
    root_element.querySelector('#hx-view-dcu').classList.remove('active');
    hxRenderMarkers();
});
root_element.querySelector('#hx-site-filter').addEventListener('change', function() {
    hxLoadMapData(this.value);
});
root_element.querySelector('#hx-token-type-filter').addEventListener('change', function() {
    hxLoadRecentTokens(this.value);
});

hxLoadSummary();
hxLoadSites();
hxLoadSiteTable();
hxLoadRecentTokens();
hxInitMap();
hxRenderTrendChart('hx-consumption-trend-chart', 'upande_hydrax.upande_hydrax.api.get_consumption_trend', 'Consumption (L)', '#3b82f6');
hxRenderTrendChart('hx-revenue-trend-chart', 'upande_hydrax.upande_hydrax.api.get_revenue_trend', 'Revenue', '#10b981');

})(typeof root_element !== 'undefined' ? root_element : (document.getElementById('hydrax-overview') || document));

style:
#hydrax-overview { font-family: inherit; }
.hx-kpi-row { display:flex; gap:12px; margin-bottom:16px; flex-wrap:wrap; }
.hx-kpi { flex:1; min-width:150px; background:var(--fg-color,#fff); border:1px solid var(--border-color,#e5e7eb); border-radius:10px; padding:12px 16px; }
.hx-kpi-label { font-size:0.72rem; font-weight:600; text-transform:uppercase; letter-spacing:0.5px; color:var(--text-muted,#6b7280); }
.hx-kpi-value { font-size:1.5rem; font-weight:700; color:var(--text-color,#111); margin:4px 0; }
.hx-kpi-sub { font-size:0.75rem; color:var(--text-muted,#6b7280); }
.hx-kpi-warn { border-color:#f59e0b; background:rgba(245,158,11,0.08); }
.hx-kpi-warn .hx-kpi-value { color:#b45309; }
.hx-kpi-warn .hx-kpi-sub { color:#b45309; }
.hx-card { background:var(--fg-color,#fff); border:1px solid var(--border-color,#e5e7eb); border-radius:12px; overflow:hidden; margin-bottom:16px; }
.hx-card-header { padding:14px 18px; border-bottom:1px solid var(--border-color,#e5e7eb); display:flex; align-items:center; justify-content:space-between; gap:10px; flex-wrap:wrap; }
.hx-card-title { font-weight:600; font-size:0.9rem; }
.hx-card-sub { font-size:0.75rem; color:var(--text-muted,#6b7280); }
.hx-toggle { display:flex; border:1px solid var(--border-color,#d1d5db); border-radius:6px; overflow:hidden; }
.hx-toggle-btn { border:none; background:transparent; color:var(--text-muted,#6b7280); padding:5px 14px; font-size:0.8rem; cursor:pointer; font-family:inherit; }
.hx-toggle-btn.active { background:#111; color:#fff; }
.hx-select { border:1px solid var(--border-color,#d1d5db); border-radius:6px; padding:5px 10px; font-size:0.8rem; background:#fff; color:var(--text-color,#111); }
.hx-legend { display:flex; gap:16px; padding:10px 18px; border-top:1px solid var(--border-color,#e5e7eb); }
.hx-legend span { display:flex; align-items:center; gap:6px; font-size:12px; color:var(--text-muted,#6b7280); }
.hx-dot { width:10px; height:10px; border-radius:50%; display:inline-block; }
#hx-map { position: relative; height: 380px; width: 100%; }
.hx-chart-body { padding:16px 18px; }
.hx-chart-empty { color:var(--text-muted,#6b7280); padding:8px 0; font-size:13px; }
.hx-grid-2 { display:grid; grid-template-columns:1fr 1fr; gap:16px; margin-bottom:16px; }
@media (max-width: 900px) { .hx-grid-2 { grid-template-columns:1fr; } }
.hx-table-wrap { overflow-x:auto; }
.hx-table { width:100%; border-collapse:collapse; font-size:0.8rem; }
.hx-table th, .hx-table td { padding:8px 18px; text-align:left; white-space:nowrap; }
.hx-table th { color:var(--text-muted,#6b7280); font-weight:600; font-size:0.7rem; text-transform:uppercase; letter-spacing:0.4px; border-bottom:1px solid var(--border-color,#e5e7eb); }
.hx-table tbody tr { border-bottom:1px solid var(--border-color,#f0f1f2); }
.hx-table tbody tr:last-child { border-bottom:none; }
.hx-table-empty { color:var(--text-muted,#6b7280); padding:14px 18px; font-size:13px; }
